import random

GROUP = "number_theory"
SKILL = "induction"


def max_divisor_size(target, min_divisor_sum, max_divisor_sum):
    if target == 0:
        return 0

    if target < min_divisor_sum:
        return -1

    max_size = 0

    for divisor_sum in range(min_divisor_sum, max_divisor_sum + 1):
        if divisor_sum <= target:
            remaining_sum = target - divisor_sum
            size = max_divisor_size(remaining_sum, min_divisor_sum, divisor_sum - 1)

            if size != -1:
                max_size = max(max_size, size + 1)

    return max_size


def generate(seed):
    rng = random.Random(seed)

    min_divisor_sum = rng.randint(3, 10)
    max_divisor_sum = rng.randint(20, 30)
    target_sum = rng.randint(15, 30)

    answer = max_divisor_size(target_sum, min_divisor_sum, max_divisor_sum)

    check = -1
    for divisor_sum in range(min_divisor_sum, max_divisor_sum + 1):
        if divisor_sum <= target_sum:
            remaining_sum = target_sum - divisor_sum
            size = max_divisor_size(remaining_sum, min_divisor_sum, divisor_sum - 1)
            if size != -1:
                check = max(check, 1 + size)

    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"Consider the sum of a set of distinct positive integers, where the sum of any subset of these integers ranges from {min_divisor_sum} to {max_divisor_sum} (inclusive). "
        f"What is the maximum number of distinct integers in this set such that no subset sum exceeds the target sum {target_sum} and all subset sums sum to exactly {target_sum}? State only the integer."
    )
    return problem, str(answer)

