def count_powers(n, min_power, max_power):
    powers = [0] * (n + 1)
    powers[0] = 1

    for k in range(min_power, max_power + 1):
        for i in range(n, k - 1, -1):
            powers[i] += powers[i - k]

    return powers[n]

def generate(seed):
    rng = random.Random(seed)

    min_power = rng.randint(2, 5)
    max_power = rng.randint(10, 20)
    threshold_count = 0

    # Find the threshold number of powers
    for i in range(min_power, max_power + 1):
        if count_powers(i, min_power, i) > 0:
            threshold_count = i
            break

    # Independent route: iterate from the minimum power count to find the smallest number that can form a valid combination.
    for i in range(min_power, max_power + 1):
        if count_powers(i, min_power, i) > 0:
            check_threshold_count = i
            break

    assert threshold_count == check_threshold_count, f"threshold_count={threshold_count} check_threshold_count={check_threshold_count}"

    problem = (
        f"Determine the smallest number of powers from {min_power} to {max_power} (inclusive) such that a set of {threshold_count} powers can be formed with each power between {min_power} and {threshold_count} (inclusive) where all powers sum to exactly {threshold_count}. State only the integer."
    )
    return problem, str(threshold_count)

